head.b:skin:
:root { --navy:#0b1730; --navy2:#18345b; --gold:#d9ad52; --ink:#182235; --muted:#5c6678; --paper:#f5f7fb; }
* { box-sizing:border-box; }
body { margin:0; background:var(--paper); color:var(--ink); font:16px/1.7 Arial,sans-serif; }
a { color:#173d70; text-decoration:none; }
a:hover { color:#9a6c13; }
img { max-width:100%; height:auto; }
.wrap { width:min(1120px,calc(100% - 32px)); margin:0 auto; }
.topbar { background:var(--navy); color:#fff; padding:8px 16px; text-align:center; font-size:13px; }
.site-header { background:linear-gradient(125deg,var(--navy),var(--navy2)); color:#fff; border-bottom:4px solid var(--gold); }
.brand-row { padding:24px 0 18px; }
.brand { margin:0; font-size:clamp(25px,4vw,38px); line-height:1.2; font-weight:800; }
.brand a { color:#fff; }
.tagline { color:#e6eaf2; margin:7px 0 0; }
.nav { display:flex; flex-wrap:wrap; gap:7px; padding:0 0 16px; }
.nav a { color:#fff; padding:8px 11px; border:1px solid rgba(255,255,255,.2); border-radius:7px; font-size:14px; }
.nav a:hover { background:var(--gold); color:var(--navy); }
.hero { margin:26px auto; padding:clamp(22px,5vw,44px); border-radius:16px; background:linear-gradient(125deg,#fff,#eef2f8); border:1px solid #e0e6ef; }
.eyebrow { color:#946a18; text-transform:uppercase; font-size:12px; font-weight:800; letter-spacing:1.4px; }
.hero h2 { margin:8px 0 12px; color:var(--navy); font-size:clamp(26px,4vw,40px); line-height:1.2; }
.hero p { max-width:760px; color:var(--muted); }
.actions { display:flex; flex-wrap:wrap; gap:10px; margin-top:20px; }
.btn { display:inline-block; background:var(--navy); color:#fff; border-radius:8px; padding:10px 16px; font-weight:700; }
.btn.gold { background:var(--gold); color:var(--navy); }
.section-title { color:var(--navy); font-size:25px; margin:28px 0 14px; }
.cards { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:15px; margin-bottom:28px; }
.service-card { background:#fff; border:1px solid #e1e7f0; border-radius:12px; padding:19px; }
.service-card h3 { margin:0 0 7px; color:var(--navy); font-size:18px; }
.service-card p { margin:0; color:var(--muted); font-size:14px; }
.content-grid { display:grid; grid-template-columns:minmax(0,2fr) minmax(220px,1fr); gap:22px; align-items:start; margin-bottom:30px; }
.main-column,.sidebar-column { min-width:0; }
.Blog .blog-posts,.post-outer,.widget { background:#fff; border:1px solid #e1e7f0; border-radius:12px; padding:20px; margin-bottom:17px; overflow-wrap:anywhere; }
.post-title,.post-title a,.post h3 { color:var(--navy); font-size:24px; line-height:1.3; }
.post-body { overflow-wrap:anywhere; }
.post-body img { max-width:100%; height:auto; }
.date-header,.post-footer,.post-timestamp { color:var(--muted); font-size:13px; }
.sidebar-column .widget h2 { color:var(--navy); font-size:18px; }
.site-footer { background:var(--navy); color:#e8edf5; margin-top:26px; padding:27px 0; }
.footer-links { display:flex; flex-wrap:wrap; gap:15px; }
.footer-links a { color:#f3d58e; }
.copyright { font-size:13px; color:#bfc9d9; margin-top:12px; }
@media (max-width:800px) { .cards { grid-template-columns:repeat(2,minmax(0,1fr)); } .content-grid { grid-template-columns:1fr; } }
@media (max-width:520px) { .wrap { width:calc(100% - 22px); } .cards { grid-template-columns:1fr; } .nav { gap:6px; } .nav a { padding:7px 9px; font-size:13px; } .hero { margin:16px auto; } .Blog .blog-posts,.post-outer,.widget { padding:15px; } }
